<template><AppShell title="店铺认证" back><view class="pad"><view class="cert-banner"><AppIcon name="shield" :size="36" /><text class="title">披露真实店铺信息</text><text class="muted">出售道具需实名认证和店铺认证；求购只需实名认证。</text></view><StateView :loading="loading&&!ready" :error="loadError" :count="ready?1:0" @retry="refresh" /><template v-if="ready&&!loadError"><button class="ui-button identity-link" @click="go('identity/index')"><text>实名认证</text><text>{{profile.realnameStatus==='VERIFIED'?'已实名':'去实名认证'}} ›</text></button><view class="card"><view class="row between"><text class="field-label">店铺认证</text><text class="tag">{{labels[profile.shopStatus||'NONE']}}</text></view><text v-if="profile.shopReviewNote" class="summary-text">审核说明：{{profile.shopReviewNote}}</text><template v-if="profile.shopSubmitted"><text class="section bold block">{{profile.shopName}}</text><text class="muted block section">{{profile.shopIntro}}</text><text class="block section">手机号码：{{profile.phoneMasked||'旧版资料待后台补验手机号'}}</text><text class="muted tiny block section">资料已提交并锁定。如需更正，联系平台由后台核验修改；审核未通过也不能自行重新上传。</text><button class="ui-button btn outline wide section" :disabled="loading" @click="refresh">刷新认证状态</button><button class="ui-button text-button wide section" @click="go('account/index',{type:'help'})">联系平台更正资料 ›</button><button v-if="canPublish(session.user)" class="ui-button btn wide section" @click="go('publish/service')">出售我的道具</button></template><template v-else><label class="field-label section">店铺名称</label><input v-model="form.shopName" @blur="form.shopName=$event.detail.value" class="text-input" maxlength="40" placeholder="2–40 字，给店铺起个名字" /><label class="field-label section">店铺介绍</label><textarea v-model="form.shopIntro" @blur="form.shopIntro=$event.detail.value" class="textarea" maxlength="500" placeholder="介绍主营道具与交易方式（至少 5 字）" /><PhoneVerification class="section block" :verified="profile.phoneVerified" :masked="profile.phoneMasked" :available="config.smsReady" @verified="refresh" /><label class="field-label section">店铺资料证明</label><text class="muted tiny block section">上传游戏资料页及持有道具的截图，最多 3 张。仅本人及店铺审核人员可见，勿上传身份证或账号密码。</text><UploadImages class="section" purpose="SHOP_CERTIFICATION" v-model="form.images" :limit="3" @busy="uploading=$event" /><view class="check-row section" @click="accepted=!accepted"><text :class="['check-box',{checked:accepted}]">{{accepted?'✓':''}}</text><text>我确认资料真实，提交后仅可由后台更改</text></view><text v-if="error" class="field-error">{{error}}</text><button class="ui-button btn wide section" :disabled="busy||uploading||loading||!profile.phoneVerified||!accepted" @click="submit">{{busy?'正在提交…':'确认并提交一次'}}</button></template></view></template></view></AppShell></template>
<script setup>
import {ref,reactive,computed,watch} from 'vue';import {onShow} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import AppIcon from '../../components/AppIcon.vue';import UploadImages from '../../components/UploadImages.vue';import StateView from '../../components/StateView.vue';import PhoneVerification from '../../components/PhoneVerification.vue';import {session,loadMe,loadConfig,request,requireLogin,go,toast,labels} from '../../lib/api';import {canPublish} from '../../lib/playerTrade'
const form=reactive({shopName:'',shopIntro:'',images:[]}),accepted=ref(false),busy=ref(false),uploading=ref(false),error=ref(''),loading=ref(false),loadError=ref(''),ready=ref(false),config=ref({});const profile=computed(()=>session.user?.playerProfile||{});const drafts=new Map();let version=0,hydratedFor=0
watch(()=>session.token,()=>{if(hydratedFor&&!profile.value.shopSubmitted)drafts.set(hydratedFor,{shopName:form.shopName,shopIntro:form.shopIntro,images:[...form.images]});version++;ready.value=false;loading.value=false;busy.value=false;uploading.value=false;error.value='';loadError.value='';accepted.value=false;hydratedFor=0;Object.assign(form,{shopName:'',shopIntro:'',images:[]})},{flush:'sync'})
onShow(()=>{if(requireLogin())refresh()})
async function refresh(){if(loading.value||!session.token)return;const token=session.token,ticket=++version;loading.value=true;loadError.value='';try{await loadMe();config.value=await loadConfig();if(token===session.token&&ticket===version){ready.value=true;if(profile.value.shopSubmitted)drafts.delete(session.user.id);if(hydratedFor!==session.user.id||profile.value.shopSubmitted){const draft=!profile.value.shopSubmitted?drafts.get(session.user.id):null;Object.assign(form,draft||{shopName:profile.value.shopName||'',shopIntro:profile.value.shopIntro||'',images:[]});hydratedFor=session.user.id}}}catch(e){if(token===session.token&&ticket===version){ready.value=false;loadError.value=e.message}}finally{if(token===session.token&&ticket===version)loading.value=false}}
async function submit(){if(busy.value||uploading.value||loading.value||!ready.value||!accepted.value)return;const token=session.token;busy.value=true;error.value='';try{await request('/boost/me/shop','POST',{...form,images:[...form.images]});await refresh();if(token===session.token)toast('店铺资料已提交并锁定，等待审核')}catch(e){if(token===session.token){error.value=e.message;await refresh();if(token===session.token&&profile.value.shopSubmitted){error.value='';toast('已核对：店铺资料已提交，请查看审核状态')}}}finally{if(token===session.token)busy.value=false}}
</script>
<style scoped>.cert-banner{display:flex;flex-direction:column;align-items:center;gap:12px;background:#fff3a8;border-radius:16px;padding:24px 18px;margin-bottom:18px;text-align:center}.cert-banner .muted{font-size:12px;line-height:1.6}.card .textarea{min-height:100px}.identity-link{display:flex;justify-content:space-between;align-items:center;width:100%;min-height:52px;text-align:left;padding:12px 16px;margin-bottom:12px;background:white;border-radius:12px;font-size:14px}.block{display:block}.check-row{align-items:flex-start;line-height:1.6;font-size:12px}</style>
